from flask import Flask, request, jsonify
import queue, time, threading

app = Flask(__name__)
waiters = []  # (cursor, queue) — in prod use Redis, not memory
LOG = []      # append-only event log with increasing ids

@app.post("/publish")
def publish():
    evt = {"id": len(LOG), "body": request.json["body"]}
    LOG.append(evt)
    for cursor, q in waiters:
        q.put(evt)  # wake only waiters behind this event
    waiters.clear()
    return {"ok": True}

@app.get("/updates")
def updates():
    cursor = int(request.args.get("after", -1))
    # 1. Fast path: replay anything already in the buffer.
    missed = [e for e in LOG if e["id"] > cursor]
    if missed:
        return jsonify(missed)
    # 2. Slow path: park up to 25s waiting for new events.
    q: queue.Queue = queue.Queue()
    waiters.append((cursor, q))
    try:
        evt = q.get(timeout=25)  # timeout -> empty list, client re-polls
        rest = [e for e in LOG if e["id"] > cursor]
        return jsonify(rest)
    except queue.Empty:
        return jsonify([])

// WebSocket client must handle what the protocol omits: re-auth,
// re-subscribe, replay, and backoff. The socket alone gives none of this.
let lastSeenId = -1;
let backoffMs = 1000;

function connect() {
  const ws = new WebSocket("wss://api.example/ws?token=" + getToken());
  ws.onopen = () => {
    backoffMs = 1000;
    // Re-subscribe WITH cursor so the server can replay the gap.
    ws.send(JSON.stringify({ type: "subscribe", after: lastSeenId }));
  };
  ws.onmessage = (e) => {
    const msg = JSON.parse(e.data);
    if (msg.id <= lastSeenId) return; // dedup on overlapping reconnects
    lastSeenId = msg.id;
    render(msg);
  };
  ws.onclose = () => {
    // Exponential backoff with jitter — never hammer the fleet.
    const jitter = Math.random() * 1000;
    setTimeout(connect, Math.min(backoffMs + jitter, 30000));
    backoffMs *= 2;
  };
  // Send heartbeat so LBs and NATs do not silently kill idle sockets.
  setInterval(() => { if (ws.readyState === 1) ws.send('{"type":"ping"}'); }, 25000);
}
